package com.saivandan.crm.security;

import org.springframework.context.annotation.*; import org.springframework.security.config.annotation.web.builders.HttpSecurity; import org.springframework.security.config.http.SessionCreationPolicy; import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.security.web.SecurityFilterChain; import org.springframework.security.web.authentication.UsernamePasswordAuthenticationFilter;

@Configuration @org.springframework.security.config.annotation.method.configuration.EnableMethodSecurity public class SecurityConfig {
  @Bean PasswordEncoder passwordEncoder(){return new BCryptPasswordEncoder();}
  @Bean SecurityFilterChain securityFilterChain(HttpSecurity http,JwtAuthFilter jwt) throws Exception {return http.csrf(c->c.disable()).cors(c->{}).sessionManagement(s->s.sessionCreationPolicy(SessionCreationPolicy.STATELESS)).authorizeHttpRequests(a->a.requestMatchers("/api/auth/login","/api/health","/error").permitAll().requestMatchers("/api/auth/users/**").hasAnyRole("ADMIN","SUPER_ADMIN").requestMatchers("/api/leads/**","/api/follow-ups/**","/api/bookings/**").hasAnyRole("ADMIN","SUPER_ADMIN","SALES_MANAGER","SALES_EXECUTIVE","MANAGEMENT","SUPPORT").requestMatchers("/api/units/**").hasAnyRole("ADMIN","SUPER_ADMIN","SALES_MANAGER","SALES_EXECUTIVE","SITE_MANAGER","MANAGEMENT").requestMatchers("/api/records/**").hasAnyRole("ADMIN","SUPER_ADMIN","SALES_MANAGER","SALES_EXECUTIVE","ACCOUNTS","FINANCE","HR_MANAGER","HR","PURCHASE_MANAGER","VENDOR","SITE_MANAGER","MANAGEMENT","SUPPORT").anyRequest().authenticated()).addFilterBefore(jwt,UsernamePasswordAuthenticationFilter.class).build();}
}
